BEGIN TRANSACTION;
DROP TABLE IF EXISTS duncle_drop_rates_synthetic_382;

CREATE TABLE IF NOT EXISTS duncle_drop_rates_synthetic_382 (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  anonymous_id TEXT NOT NULL UNIQUE,
  source TEXT NOT NULL DEFAULT 'nexon',
  endkeeper_clear INTEGER NOT NULL DEFAULT 0,
  primeval_oath_count INTEGER NOT NULL DEFAULT 0,
  primeval_oath_rate REAL NOT NULL DEFAULT 0,
  primeval_crystal_count INTEGER NOT NULL DEFAULT 0,
  primeval_crystal_rate REAL NOT NULL DEFAULT 0,
  season_key TEXT NOT NULL DEFAULT 'synthetic_382',
  is_hidden INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_duncle_synthetic_382_hidden ON duncle_drop_rates_synthetic_382(is_hidden);
CREATE INDEX IF NOT EXISTS idx_duncle_synthetic_382_updated ON duncle_drop_rates_synthetic_382(updated_at);
COMMIT;
